package curated

import (
	"fmt"
	stream "github.com/KromDaniel/regengo/stream"
	"regexp"
	"strings"
	"testing"
)

// Code generated by regengo
// Tests and benchmarks for pattern: (a+)+b

var thompsonCatastrophicRegexp = regexp.MustCompile("(a+)+b")

var thompsonCatastrophicTestInputs = []string{"example"}

func TestThompsonCatastrophicMatchString(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		expected := thompsonCatastrophicRegexp.MatchString(input)
		got := ThompsonCatastrophic{}.MatchString(input)
		if got != expected {
			t.Errorf("MatchString(%q) = %v, want %v", input, got, expected)
		}
	}
}

func TestThompsonCatastrophicMatchBytes(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		inputBytes := []byte(input)
		expected := thompsonCatastrophicRegexp.Match(inputBytes)
		got := ThompsonCatastrophic{}.MatchBytes(inputBytes)
		if got != expected {
			t.Errorf("MatchBytes(%q) = %v, want %v", input, got, expected)
		}
	}
}

func TestThompsonCatastrophicFindString(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		expectedMatches := thompsonCatastrophicRegexp.FindStringSubmatch(input)
		result, ok := ThompsonCatastrophic{}.FindString(input)

		if len(expectedMatches) > 0 {
			if !ok {
				t.Errorf("FindString(%q) returned false, expected match", input)
				continue
			}
			if result.Match != expectedMatches[0] {
				t.Errorf("FindString(%q).Match = %q, want %q", input, result.Match, expectedMatches[0])
			}
			{
				if result.Group1 != expectedMatches[1] {
					t.Errorf("FindString(%q).Group1 = %q, want %q", input, result.Group1, expectedMatches[1])
				}
			}
		} else {
			if ok {
				t.Errorf("FindString(%q) returned true, expected no match", input)
			}
		}
	}
}

func TestThompsonCatastrophicFindAllString(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		expectedAll := thompsonCatastrophicRegexp.FindAllStringSubmatch(input, -1)
		results := ThompsonCatastrophic{}.FindAllString(input, -1)

		if len(results) != len(expectedAll) {
			t.Errorf("FindAllString(%q, -1) returned %d results, want %d", input, len(results), len(expectedAll))
			continue
		}
		for i := range results {
			if results[i].Match != expectedAll[i][0] {
				t.Errorf("FindAllString(%q, -1)[%d].Match = %q, want %q", input, i, results[i].Match, expectedAll[i][0])
			}
			{
				if results[i].Group1 != expectedAll[i][1] {
					t.Errorf("FindAllString(%q, -1)[%d].Group1 = %q, want %q", input, i, results[i].Group1, expectedAll[i][1])
				}
			}
		}
	}
}

func BenchmarkThompsonCatastrophic(b *testing.B) {
	inputs := thompsonCatastrophicTestInputs

	b.Run("Match", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = thompsonCatastrophicRegexp.MatchString(input)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = ThompsonCatastrophic{}.MatchString(input)
					}
				})
			})
		}
	})

	b.Run("FindFirst", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = thompsonCatastrophicRegexp.FindStringSubmatch(input)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_, _ = ThompsonCatastrophic{}.FindString(input)
					}
				})
				b.Run("regengo_reuse", func(b *testing.B) {
					b.ReportAllocs()
					var result *ThompsonCatastrophicResult
					for b.Loop() {
						result, _ = ThompsonCatastrophic{}.FindStringReuse(input, result)
					}
				})
			})
		}
	})

	b.Run("FindAll", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = thompsonCatastrophicRegexp.FindAllStringSubmatch(input, -1)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = ThompsonCatastrophic{}.FindAllString(input, -1)
					}
				})
				b.Run("regengo_append", func(b *testing.B) {
					b.ReportAllocs()
					results := make([]*ThompsonCatastrophicResult, 0, 100)
					for b.Loop() {
						results = ThompsonCatastrophic{}.FindAllStringAppend(input, -1, results[:0])
					}
				})
			})
		}
	})

}

func TestThompsonCatastrophicFindReader(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		// Get expected matches from stdlib
		expectedAll := thompsonCatastrophicRegexp.FindAllString(input, -1)

		// Get matches from streaming API
		var streamMatches []string
		err := ThompsonCatastrophic{}.FindReader(strings.NewReader(input), stream.Config{}, func(m stream.Match[*ThompsonCatastrophicBytesResult]) bool {
			streamMatches = append(streamMatches, string(m.Result.Match))
			return true
		})
		if err != nil {
			t.Errorf("FindReader(%q) error: %v", input, err)
			continue
		}

		// Compare results
		if len(streamMatches) != len(expectedAll) {
			t.Errorf("FindReader(%q) got %d matches, want %d", input, len(streamMatches), len(expectedAll))
			continue
		}
		for i := range streamMatches {
			if streamMatches[i] != expectedAll[i] {
				t.Errorf("FindReader(%q)[%d] = %q, want %q", input, i, streamMatches[i], expectedAll[i])
			}
		}
	}
}

func TestThompsonCatastrophicFindReaderCount(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		expectedAll := thompsonCatastrophicRegexp.FindAllString(input, -1)
		expected := int64(len(expectedAll))

		count, err := ThompsonCatastrophic{}.FindReaderCount(strings.NewReader(input), stream.Config{})
		if err != nil {
			t.Errorf("FindReaderCount(%q) error: %v", input, err)
			continue
		}
		if count != expected {
			t.Errorf("FindReaderCount(%q) = %d, want %d", input, count, expected)
		}
	}
}

func TestThompsonCatastrophicFindReaderFirst(t *testing.T) {
	for _, input := range thompsonCatastrophicTestInputs {
		expected := thompsonCatastrophicRegexp.FindString(input)

		result, _, err := ThompsonCatastrophic{}.FindReaderFirst(strings.NewReader(input), stream.Config{})
		if err != nil {
			t.Errorf("FindReaderFirst(%q) error: %v", input, err)
			continue
		}

		if expected == "" {
			if result != nil {
				t.Errorf("FindReaderFirst(%q) = %q, want no match", input, string(result.Match))
			}
		} else {
			if result == nil {
				t.Errorf("FindReaderFirst(%q) = nil, want %q", input, expected)
			} else if string(result.Match) != expected {
				t.Errorf("FindReaderFirst(%q) = %q, want %q", input, string(result.Match), expected)
			}
		}
	}
}

func TestThompsonCatastrophicMatchLengthInfo(t *testing.T) {
	minLen, maxLen := ThompsonCatastrophic{}.MatchLengthInfo()
	// Just verify we get sensible values
	if minLen < 0 {
		t.Errorf("MinMatchLen = %d, expected >= 0", minLen)
	}
	if maxLen != -1 && maxLen < minLen {
		t.Errorf("MaxMatchLen = %d < MinMatchLen = %d", maxLen, minLen)
	}
}
